/*
 * A167698  Number of reduced words of length n in Coxeter group on 27
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^15 = I.
 * https://oeis.org/A167698
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) satisfies the recurrence * a(n) = 25·(a(n-1)+⋯+a(n-14)) –
 *            325·a(n-15) for n ≥ 16, * a(15)=25·(a(14)+⋯+a(1)) – 325·a(0) +
 *            1. * * The first 15 values (index 0‑14) are taken from the OEIS
 *            data. * Subsequent terms are generated by the recurrence above.
 *            * The sequence is cached in a static array...
 * Range:     u8 n <= 1, u16 n <= 3, u32 n <= 6, u64 n <= 13, u128 n <= 27,
 *            big any n
 * Helpers:   seq_from_str
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "../utils/seq_from_str.h"

seq_t a(idx_t n)
{
    /* static cache of computed values */
    static seq_t *cache = NULL;      /* pointer to cache array           */
    static idx_t cache_len = 0;      /* number of computed terms (>=1)   */

    /* initialise the first 15 terms once */
    if (cache == NULL) {
        cache_len = 15;
        cache = (seq_t*)malloc(cache_len * sizeof(seq_t));
        cache[0]  = seq_from_str("1");
        cache[1]  = seq_from_str("27");
        cache[2]  = seq_from_str("702");
        cache[3]  = seq_from_str("18252");
        cache[4]  = seq_from_str("474552");
        cache[5]  = seq_from_str("12338352");
        cache[6]  = seq_from_str("320797152");
        cache[7]  = seq_from_str("8340725952");
        cache[8]  = seq_from_str("216858874752");
        cache[9]  = seq_from_str("5638330743552");
        cache[10] = seq_from_str("146596599332352");
        cache[11] = seq_from_str("3811511582641152");
        cache[12] = seq_from_str("99099301148669952");
        cache[13] = seq_from_str("2576581829865418752");
        cache[14] = seq_from_str("66991127576500887552");
    }

    /* return immediately if we already have the value */
    if (n < cache_len)
        return cache[n];

    /* extend the cache up to index n */
    idx_t old_len = cache_len;
    cache = (seq_t*)realloc(cache, (n + 1) * sizeof(seq_t));
    cache_len = n + 1;                     /* now we have room for indices 0..n */

    /* compute missing terms */
    for (idx_t cur = old_len; cur <= n; ++cur) {
        seq_t sum = 0;
        for (idx_t j = 1; j <= 14; ++j)
            sum += cache[cur - j];
        seq_t val = 25 * sum - 325 * cache[cur - 15];
        if (cur == 15)                 /* special constant for n = 15 */
            val += 1;
        cache[cur] = val;
    }

    return cache[n];
}
